### 5. `src/components/LoginForm.jsx`

```jsx
import React, { useState } from 'react';

/**
 * LoginForm
 *
 * - Uses React hooks (useState) to manage form state.
 * - Validates that both fields are non‑empty before submitting.
 * - Simulates an API call with a timeout.
 * - Shows success or error message.
 */
const LoginForm = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState('idle'); // idle | loading | success | error
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Basic client‑side validation
    if (!email.trim() || !password.trim()) {
      setError('الرجاء ملء جميع الحقول.');
      setStatus('error');
      return;
    }

    setStatus('loading');
    setError('');

    try {
      // ---- هنا يتم إرسال الطلب إلى الخادم ----
      // const response = await fetch('/api/login', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify({ email, password }),
      // });
      // const data = await response.json();

      // For demo purposes, we fake a successful login after 1.5s
      await new Promise((resolve) => setTimeout(resolve, 1500));

      // Assume success
      setStatus('success');
    } catch (err) {
      setError('فشل تسجيل الدخول. حاول مرة أخرى.');
      setStatus('error');
    }
  };

  return (
    <form className="login-form" onSubmit={handleSubmit}>
      <label>
        البريد الإلكتروني:
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
      </label>

      <label>
        كلمة المرور:
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
      </label>

      <button type="submit" disabled={status === 'loading'}>
        {status === 'loading' ? 'جارٍ تسجيل الدخول...' : 'تسجيل الدخول'}
      </button>

      {status === 'error' && <p className="error">{error}</p>}
      {status === 'success' && (
        <p className="success">تم تسجيل الدخول بنجاح!</p>
      )}
    </form>
  );
};

export default LoginForm;
```

